import React, { useEffect, useState } from "react";
import axios from "axios";
import RunHistory from "./components/RunHistory";

const savedFusionBaseUrl = localStorage.getItem("fusionBaseUrl") || "";
const savedFusionUsername = localStorage.getItem("fusionUsername") || "";

function App() {
  const [runs, setRuns] = useState([]);
  const [orgCodes, setOrgCodes] = useState("");
  const [fusionCredentials, setFusionCredentials] = useState({
    baseUrl: savedFusionBaseUrl,
    username: savedFusionUsername,
    password: "",
  });
  const [authenticated, setAuthenticated] = useState(false);
  const [loginLoading, setLoginLoading] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);

  const fetchHistory = async () => {
    try {
      const res = await axios.get("/api/extraction/history");
      setRuns(res.data);
    } catch (err) {
      console.error("Failed to load history", err);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, []);

  const handleCredentialChange = (field, value) => {
    setFusionCredentials((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const handleLogin = async (event) => {
    event.preventDefault();
    setLoginLoading(true);
    setMessage(null);

    try {
      const res = await axios.post("/api/auth/login", fusionCredentials);
      localStorage.setItem("fusionBaseUrl", res.data.fusion.baseUrl);
      localStorage.setItem("fusionUsername", res.data.fusion.username);
      setFusionCredentials((current) => ({
        ...current,
        baseUrl: res.data.fusion.baseUrl,
        username: res.data.fusion.username,
      }));
      setAuthenticated(true);
      setMessage({ type: "success", text: "Fusion login successful." });
    } catch (err) {
      const errText = err.response?.data?.error || err.message;
      setAuthenticated(false);
      setMessage({ type: "error", text: errText });
    } finally {
      setLoginLoading(false);
    }
  };

  const handleLogout = () => {
    setAuthenticated(false);
    setFusionCredentials((current) => ({
      ...current,
      password: "",
    }));
    setMessage(null);
  };

  const handleRun = async () => {
    setLoading(true);
    setMessage(null);
    try {
      const res = await axios.post("/api/extraction/run", {
        orgCodes,
        fusionCredentials,
      });
      setMessage({ type: "success", text: `Done — ${res.data.run.subinventoryCount} subinventories, ${res.data.run.locatorCount} locators.` });
      await fetchHistory();
    } catch (err) {
      const errText = err.response?.data?.error || err.message;
      setMessage({ type: "error", text: errText });
      await fetchHistory();
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="app">
      <h1>ConfigSnapshot</h1>
      <p className="subtitle">Subinventory & Locator extraction from Oracle Fusion Cloud</p>

      {!authenticated ? (
        <form className="login-panel" onSubmit={handleLogin}>
          <label htmlFor="fusion-base-url">Fusion Base URL</label>
          <input
            id="fusion-base-url"
            value={fusionCredentials.baseUrl}
            onChange={(event) => handleCredentialChange("baseUrl", event.target.value)}
            placeholder="https://your-instance.fa.us2.oraclecloud.com"
            disabled={loginLoading}
            required
          />

          <label htmlFor="fusion-username">Fusion Username</label>
          <input
            id="fusion-username"
            value={fusionCredentials.username}
            onChange={(event) => handleCredentialChange("username", event.target.value)}
            placeholder="readonly.integration.user"
            disabled={loginLoading}
            required
          />

          <label htmlFor="fusion-password">Fusion Password</label>
          <input
            id="fusion-password"
            type="password"
            value={fusionCredentials.password}
            onChange={(event) => handleCredentialChange("password", event.target.value)}
            placeholder="Password"
            disabled={loginLoading}
            required
          />

          <button type="submit" disabled={loginLoading}>
            {loginLoading ? "Checking..." : "Login"}
          </button>
        </form>
      ) : (
        <>
          <div className="session-bar">
            <span>Logged in as {fusionCredentials.username}</span>
            <button className="secondary-button" onClick={handleLogout} disabled={loading}>
              Logout
            </button>
          </div>

          <div className="run-panel">
            <label htmlFor="org-codes">Organization name or code</label>
            <div className="run-controls">
              <input
                id="org-codes"
                value={orgCodes}
                onChange={(event) => setOrgCodes(event.target.value)}
                placeholder="ALL, Vision Operations, M1"
                disabled={loading}
              />
              <button onClick={handleRun} disabled={loading}>
                {loading ? "Running..." : "Run Extraction"}
              </button>
            </div>
            <p className="helper-text">Separate multiple organizations with commas. Leave blank to use backend .env default.</p>
          </div>
        </>
      )}

      {message && (
        <p className={message.type === "success" ? "status-ok" : "status-fail"}>{message.text}</p>
      )}

      <h2>Run History</h2>
      <RunHistory runs={runs} />
    </div>
  );
}

export default App;
